void shouldThrowWhenBlankWordReturned() {
    when(callResponse.content()).thenReturn(" ");

    assertThatThrownBy(() -> chatService.startGame())
            .isInstanceOf(IllegalStateException.class)
            .hasMessageContaining("No word given");
}

