@Data
public class Game {
    @Schema(name = "word", example = "butter", maxLength = 255, description = "The word to guess")
    String word;
    @Schema(name = "prompts", example = "1", maxLength = 255, description = "Amount of question asked")
    int prompts;
    @Schema(name = "guessed", example = "false", maxLength = 255, description = "Is the word guessed")
    boolean guessed;

    public Game(String word) {
        this.word = word;
        this.prompts = 0;
        this.guessed = false;
    }

    public void incrementPrompts() {
        this.prompts++;
    }
}

public void incrementPrompts() {
    this.prompts++;
}

@AllArgsConstructor
@Data
public class GameRequest {
    @Schema(name = "message", example = "Is it black?", maxLength = 255, description = "Question to LLM")
    private String message;
    private Game game;
}

@AllArgsConstructor
@Data
public class ChatResponse {
    private String answer;
    private boolean won;
}

@AllArgsConstructor
@Data
public class Response {
    @Schema(name = "message", example = "YES", maxLength = 255, description = "The answer from chat")
    private String message;
    @Schema(name = "won", example = "false", maxLength = 255, description = "Is the word guessed")
    private boolean won;
    @Schema(name = "promptsUsed", example = "3", maxLength = 255, description = "Amount of question asked")
    private int promptsUsed;
}

